CREATE TABLE IF NOT EXISTS visitors (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT NOT NULL UNIQUE, name TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS draws (id INTEGER PRIMARY KEY AUTOINCREMENT, visitor_id INTEGER NOT NULL, hexagram_number INTEGER NOT NULL CHECK(hexagram_number BETWEEN 1 AND 64), drawn_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(visitor_id) REFERENCES visitors(id));
CREATE TABLE IF NOT EXISTS consents (id INTEGER PRIMARY KEY AUTOINCREMENT, visitor_id INTEGER NOT NULL, marketing_consent INTEGER NOT NULL, policy_version TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(visitor_id) REFERENCES visitors(id));
CREATE TABLE IF NOT EXISTS email_deliveries (id INTEGER PRIMARY KEY AUTOINCREMENT, draw_id INTEGER NOT NULL, status TEXT NOT NULL, provider_id TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(draw_id) REFERENCES draws(id));
CREATE INDEX IF NOT EXISTS idx_draws_visitor ON draws(visitor_id,drawn_at);
